  var add = [{"title": "寰宇纪元·大世界舆图层志·寰宇 · 新手谷与练级区", "content": "【舆图层志 · 寰宇 · 新手谷与练级区】三区起点，低等级地图与首杀。本层共 12 个节点：4 个真实地标 + 8 个网游通用设施。\n新手村 · 野狼谷：东境·月恒服的新手阶段起点，玩家在此完成转正；野狗村是同一片区域的旧称说法（原著地图索引）\n暮光城 · 浅水沼泽：北境·灵恸服的前期主城与练级区，雪月工作室在这一带势力最盛（原著地图索引）\n天空之城 · 果林地：中天·天纵服的中国区三大主城之一，出售极品货色，是最富裕的交易集散地（原著地图索引）\n毒蜂林 · 蜂巢：中天新手阶段的练级区，蜂王巢的怪物强度略高于毒蜂林本身（原著地图索引）\n传送阵：传送到本界已解锁主城，消耗少量金币；跨区传送会同步切换所在分区与第二资源。\n拍卖行：玩家挂单买卖装备与材料，价格随行就市，成交写入金币。\n铁匠铺：强化、修理与打造装备，强化成功率由引擎确定性结算，失败不毁装。\n药店：购买红蓝药水与解除减益的药剂，使用后写入 Buff 状态。\n任务公告板：接取主线、日常与悬赏任务，进度写入任务日志。\n仓库：存放背包放不下的装备与材料，按格子收费。\n装备鉴定所：鉴定未知道具的真实品级与词条，未鉴定前不显示数值。\n新手训练场：低阶怪物的练级区，复活不扣经验，适合刚开号的那几十级。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "图层志", "wangyou", "start"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 新手谷与练级区·设施清单", "content": "【寰宇 · 新手谷与练级区】本层设施共 8 处：传送阵、拍卖行、铁匠铺、药店、任务公告板、仓库、装备鉴定所、新手训练场。设施为网游通用设施，属引擎口径，不是原著逐字地名；玩家可自由赋予本界细节。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "设施", "wangyou", "start"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 主城与行会", "content": "【舆图层志 · 寰宇 · 主城与行会】转职、建帮令、驻地争夺与行会义务。本层共 12 个节点：4 个真实地标 + 8 个网游通用设施。\n银月城 · 城郊：东境中国区主城，全球战与守城战的主场；城内有一间被玩家称为全银月城最好的铁匠铺（原著地图索引）\n白云城 · 冰原：北境中期主城，白云城外血染天与书生威震白云城是北境早期最有名的两场战役（原著地图索引）\n天空之城 · 领空：中天三大主城之首，国战后的君主分离状态让这座城成为所有版本更迭的见证（原著地图索引）\n连云城 · 血战台：东境中期主城，连云城血战是版本史上标志性战役之一，也是行会矛盾的引爆点（原著地图索引）\n公会大厅：创建或加入行会，领取行会任务与驻地俸禄，贡献计入面板。\n竞技场：玩家切磋与排名赛，对手按你的实际战力缩放，胜负都不必然。\n副本入口：组队进入限时副本，通关掉落按本界品级序列结算。\n坐骑管理员：召唤、喂食与培养坐骑，成长值影响移动与属性。\n宠物围栏：孵化与喂养宠物，出战提供战斗加成，进化失败只回退一阶。\n组队招募处：发布与响应组队邀请，队伍上限五人，队友等级随招募自动对齐。\n营地商人：出售回城卷与野外补给，价格随分区行情浮动。\n技能导师：学习本职业技能、洗点与转职引导。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "图层志", "wangyou", "city"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 主城与行会·设施清单", "content": "【寰宇 · 主城与行会】本层设施共 8 处：公会大厅、竞技场、副本入口、坐骑管理员、宠物围栏、组队招募处、营地商人、技能导师。设施为网游通用设施，属引擎口径，不是原著逐字地名；玩家可自由赋予本界细节。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "设施", "wangyou", "city"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 副本与秘境", "content": "【舆图层志 · 寰宇 · 副本与秘境】首杀争夺、限时副本与材料产出。本层共 12 个节点：4 个真实地标 + 8 个网游通用设施。\n恐惧墓穴 · 墓道：北境中期的副本与练级区，另有守墓人相关的乌木鬼屋说法，两者常被混称（原著地图索引）\n浮雷古刹 · 雷阵：中天新手副本，浮雷阵与沉雷地狱是副本内的两个房间（原著地图索引）\n龙语冰川 · 裂隙：北境隐藏地图与结局新地图，冰兰牺牲后形成，覆盖北境大陆约十分之一的土地（原著地图索引）\n精灵圣殿：中天国战与领地战场景，精灵圣殿一战中战天盟一群精锐被杀进圣殿（原著补录 · 三部曲合并）\n世界 BOSS 祭坛：定时刷新世界首领，参与击杀记入战斗日志与成就，首杀全服公示。\n秘境传送门：定向传送进入深层秘境，消耗比普通传送更多的金币。\n精英巢穴：高密度精英怪的聚集地，掉落密度高于野外，死亡率也更高。\n野外营地：组队休整与补给点，HP/MP 回满并清空部分减益。\n材料采集点：采集生活技能的原料点，刷新有周期，品质随分区上浮。\n炼金工坊：把采集来的原料炼成药剂，是药剂师与召唤师的补给来源。\n强化工坊：高阶强化台，成功率高于铁匠铺，代价是更贵的材料与手续费。\n地摊市场：小号摆摊与倒卖装备的第一桶金来源，也是套利空间的温床。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "图层志", "wangyou", "deep"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 副本与秘境·设施清单", "content": "【寰宇 · 副本与秘境】本层设施共 8 处：世界 BOSS 祭坛、秘境传送门、精英巢穴、野外营地、材料采集点、炼金工坊、强化工坊、地摊市场。设施为网游通用设施，属引擎口径，不是原著逐字地名；玩家可自由赋予本界细节。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "设施", "wangyou", "deep"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 跨服战场", "content": "【舆图层志 · 寰宇 · 跨服战场】三服合流、攻城与战盟争霸。本层共 12 个节点：4 个真实地标 + 8 个网游通用设施。\n白马平原 · 国战：中天国战的主战场，最终决战青兽于此，王者权杖得以守住（原著地图索引）\n王者之都 · 要塞：北境的主城要塞与战场群之一，国战主战场（原著补录 · 三部曲合并）\n战争之地 · 精灵圣殿：中天国战与领地战的场景，精灵圣殿一战是三服合流前的最后一次大混战（原著补录 · 三部曲合并）\n荣耀主城 · 领地：东境中期主城，也是跨国主城战的收官点与跨国界势力角力的核心（原著地图索引）\n跨服传送门：只在合流赛季开放，通往寰宇中枢的其他分区战场。\n攻城器械库：战盟攻城时的装备投放点，器械有耐久，消耗战盟资源。\n战盟议事厅：战盟的顶层组织机构，一枚席位可同时在三区持有。\n军需官：按战功与贡献发放军需，声望与荣誉在这里兑换稀有装备与称号。\n战场补给点：战场内唯一的补给点，位置固定但每场都会换。\n复活祭坛：战场复活点，红名与罪恶值状态下的复活费用翻倍。\n荣誉兑换官：用声望与战功兑换稀有装备、称号与坐骑。\n敌营情报站：刺探敌方调度的据点，收益与被反刺的风险成正比。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "图层志", "wangyou", "cross"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 跨服战场·设施清单", "content": "【寰宇 · 跨服战场】本层设施共 8 处：跨服传送门、攻城器械库、战盟议事厅、军需官、战场补给点、复活祭坛、荣誉兑换官、敌营情报站。设施为网游通用设施，属引擎口径，不是原著逐字地名；玩家可自由赋予本界细节。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "设施", "wangyou", "cross"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 天梯与传承试炼", "content": "【舆图层志 · 寰宇 · 天梯与传承试炼】隐藏职业转职与跨服传承。本层共 12 个节点：4 个真实地标 + 8 个网游通用设施。\n轩辕 · 神兵冢：中天的神兵冢，十二神兵与上古神器埋藏之处，强者终局的门槛（原著地图索引）\n月神殿 · 禁地：东境后期的高级地图之一，林凡的龙骑之力与这一带的封印紧密相连（原著补录 · 三部曲合并）\n龙域 · 高地：东境与北境各有一处同名地图但并非同一片；此处在寰宇赛季被并入天梯（原著地图索引）\n帝海 · 城关：中天的城关要地，帝海盾的传说与神将之路都从这里开始（原著地图索引）\n传承祭坛：跨服传承的唯一入口，把别区的隐藏职业传承到本区，代价极高。\n觉醒法阵：隐藏职业的觉醒试炼，门槛随赛季节点提高。\n试炼场：按层数递增的独立试炼，失败只损失一次进场费。\n导师之塔：各区职业导师的驻所，高阶导师只在赛季后半程现身。\n封印解除处：解除上古封印的地方，每解一处都会改变本区的怪物强度。\n图鉴收藏家：收集图鉴与残页，凑齐一套会解锁称号与坐骑外观。\n记忆回廊：回看本区主线关键场面的副本场景，玩家可以反复看。\n跨服传承官：受理跨服传承申请，审查资历、声望与贡献三项门槛。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "图层志", "wangyou", "trial"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 天梯与传承试炼·设施清单", "content": "【寰宇 · 天梯与传承试炼】本层设施共 8 处：传承祭坛、觉醒法阵、试炼场、导师之塔、封印解除处、图鉴收藏家、记忆回廊、跨服传承官。设施为网游通用设施，属引擎口径，不是原著逐字地名；玩家可自由赋予本界细节。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "设施", "wangyou", "trial"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 神域终局", "content": "【舆图层志 · 寰宇 · 神域终局】战盟争霸、赛季收官与王者权杖。本层共 12 个节点：4 个真实地标 + 8 个网游通用设施。\n王者权杖 · 王座：不是装备而是终局凭据，它决定的是赛季归属而不是个人战力（原著地图索引）\n寰宇中枢 · 赛季广场：合流赛季的集散地，三区玩家在这里第一次真正站在同一片地面上（网游通用设施 · 引擎口径）\n天空之城 · 神座：中天主城的最高处，只有站上过神座的人才知道王座后面是什么（原著补录 · 三部曲合并）\n银月城 · 守城者：东境守城战的收官点，一座城守住一次赛季，三服都记得（原著补录 · 三部曲合并）\n诸神黄昏祭坛：赛季最终首领的祭坛，全球同刻刷新，跨服玩家共战。\n赛季结算台：结算赛季贡献与排名，发放称号、坐骑与荣誉。\n传说见证者：记录并复述上一赛季的传奇，被他记下名字的人不会消失。\n万象归寂：赛季末的终局副本，只有通关的玩家能带走自己的东西。\n纪元之眼：观测赛季走向的装置，据说它能提前看到合流名单。\n万界商会：三区合流后的最大商会，价格最贵但成色最稳。\n王者加冕台：赛季王的加冕处，规则由守擂者自己定。\n归途传送阵：赛季结束后唯一的离场通道，所有未结算的赌注在这里清零。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "图层志", "wangyou", "end"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·大世界舆图层志·寰宇 · 神域终局·设施清单", "content": "【寰宇 · 神域终局】本层设施共 8 处：诸神黄昏祭坛、赛季结算台、传说见证者、万象归寂、纪元之眼、万界商会、王者加冕台、归途传送阵。设施为网游通用设施，属引擎口径，不是原著逐字地名；玩家可自由赋予本界细节。", "category": "地理志", "tags": ["寰宇纪元", "舆图", "设施", "wangyou", "end"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·分区专名·东境·月恒服", "content": "【东境·月恒服】东境月恒服是三大分区中人口最多的一服，行会垄断程度最重，装备品级链最短。本区装备品级叫法：绿装→蓝装→紫装→圣器→神装。本区真实地标：银月城、飓风城、疾风城、连云城、荣耀主城、凌通城、野狼谷、松木林、瘟疫墓地、龙域、夜幕高地、亡灵峡谷、通灵塔、荣耀城。", "category": "地理", "tags": ["寰宇纪元", "分区", "东境", "wangyou"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·分区专名·北境·灵恸服", "content": "【北境·灵恸服】北境灵恸服地貌以冰原、雪域与龙域裂隙为主，装备品级链是三大分区里最长的。本区装备品级叫法：粗糙品→白色装→黑铁器→青铜器→白银器→黄金器→暗金器→地器→天器→鬼器→仙器→旷世圣器→神器。本区真实地标：暮光城、白云城、浅水沼泽、恶狼岭、鬼王坡、赤焰海、恐惧墓穴、白骨荒野、迷雾小镇、羽月废墟、噩梦森林、落羽山、断魂谷、豺狼谷、浮冰塔、古秦荒冢、古秦大殿、青蟒沼泽、秋风镇、暴风戈壁、海底之城、王者之都、枫林要塞、纵横古战场、龙域、龙语冰川、圣盔城、火龙城、清风城、血色要塞。", "category": "地理", "tags": ["寰宇纪元", "分区", "北境", "wangyou"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·分区专名·中天·天纵服", "content": "【中天·天纵服】中天天纵服地貌以浮空岛与空中回廊为主，竞技场、名将对战与国战节奏在三服里最快。本区装备品级叫法：白色→黑石器→青铜器→玄铁器→白银器→黄金器→暗金器→紫金器→灵器→仙器→圣器→七十二鬼器→神器→十二神兵。本区真实地标：天空之城、神隐城、天风城、白马平原、浮冰城、晨曦城、果林地、毒蜂林、蜂王巢、浮雷古刹、浮雷阵、沉雷地狱、混乱冰窟、极冰大殿、万毒窟、食人花墓地、恶魔灵堂、锁魔塔、颅骨城堡、幽魂炼阵、白垩荒原、龙陨湖、灼热洞穴、火刃谷、战争之地、神迹、精灵圣殿、日落城、乱尸领、余杭古镇。", "category": "地理", "tags": ["寰宇纪元", "分区", "中天", "wangyou"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·分区专名·寰宇中枢·神域", "content": "【寰宇中枢·神域】合流赛季开放的顶层区域，跨服战场、世界首领总巢、战盟争霸与王者权杖终局都在这里结算。本区装备品级叫法：跨服通用链：白装→…→旷世圣器→神装。本区真实地标：寰宇中枢、赛季广场、跨服战场、深渊前线、世界首领总巢、传承祭坛、觉醒法阵、归途传送阵。", "category": "地理", "tags": ["寰宇纪元", "分区", "寰宇中枢", "wangyou"], "alwaysInclude": false, "priority": ""}, {"title": "寰宇纪元·品级对照表·三区叫法与十六阶链", "content": "十六阶统一链（自低到高）：白装、绿装、蓝装、紫装、黑铁器、青铜器、玄铁器、白银器、黄金器、暗金器、灵器、鬼器、仙器、圣器、旷世圣器、神装。东境月恒服叫绿色装备、蓝色装备、紫色装备、圣器、神器；北境灵恸服叫粗糙品、白色装、黑铁器、青铜器、白银器、黄金器、暗金器、地器、天器、鬼器、仙器、旷世圣器、神器；中天天纵服叫白色、黑石器、青铜器、玄铁器、白银器、黄金器、暗金器、紫金器、灵器、仙器、圣器、七十二鬼器、神器、十二神兵。对照：地器与天器与紫金器同属「灵器」阶；七十二鬼器与旷世圣器同属「旷世圣器」阶；神器与十二神兵同属「神装」阶。正文写当前所在区的叫法，跨服对照时须明示两套叫法等价。", "category": "装备", "tags": ["寰宇纪元", "品级", "对照", "wangyou"], "alwaysInclude": false, "priority": ""}];
